def can_transform(n, a, b):
    a.sort()
    b.sort()

    used = [False] * n

    for i in range(n):
        if a[i] < b[i] and (b[i] // 2) not in b:
            return "NO"
        if a[i] == b[i]:
            continue
        if a[i] > b[i]:
            for j in range(n):
                if b[j] == a[i] and not used[j]:
                    used[j] = True
                    break
                if b[j] > a[i] and b[j] % 2 == 0 and b[j] // 2 == a[i]:
                    used[j] = True
                    break
            else:
                return "NO"
    return "YES"

def main():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        b = list(map(int, input().split()))
        result = can_transform(n, a, b)
        print(result)

if __name__ == "__main__":
    main()
